class BankTask implements Runnable {String act;BankTask(String a){act=a;}public void run(){for(int i=1;i<=3;i++){System.out.println(Thread.currentThread().getName()+" "+act+" "+i);try{Thread.sleep(300);}catch(Exception e){}}}}
